/**
 * US traffic deaths per VMT vs peer high-income countries.
 *
 * Primary US series: NHTSA FARS / Traffic Safety Facts (deaths per 100M VMT).
 * Peer distance risk: OECD/ITF IRTAD Road Safety Annual Reports (deaths per
 * billion vehicle-km), converted to per 100M VMT via 1 mi = 1.609344 km
 * (?? 6.213711922). CDC MMWR 2022 supplies a 2019 multi-country ladder.
 */

export const KM_PER_MILE = 1.609344;
/** Billion vkm per 100 million VMT */
export const BILLION_VKM_PER_100M_VMT = 100 / (KM_PER_MILE * 10); // ??? 6.2137

export function perBillionVkmToPer100mVmt(rate: number): number {
  return rate / BILLION_VKM_PER_100M_VMT;
}

export function per100mVmtToPerBillionVkm(rate: number): number {
  return rate * BILLION_VKM_PER_100M_VMT;
}

