                    </Scatter>
                  </ScatterChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </div>
        </div>
      ) : null}

      {view === "lens" ? (
        <ChartCard
          title="Two lenses, same countries"
          subtitle="Population mortality (2022, IRTAD) vs distance risk (2019, CDC MMWR) ??? US outlier on both"
        >
          <div className="h-[400px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={dualLens}
                margin={{ top: 8, right: 12, left: 0, bottom: 48 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  dataKey="label"
                  tick={{ fontSize: 10 }}
                  interval={0}
                  angle={-35}
                  textAnchor="end"
                  height={60}
                />
                <YAxis
                  yAxisId="left"
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Per 100k pop",
                    angle: -90,
                    position: "insideLeft",
                    style: { fontSize: 11, fill: SLATE },
                  }}
                />
                <YAxis
                  yAxisId="right"
                  orientation="right"
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Per 100M VMT",
                    angle: 90,
                    position: "insideRight",
                    style: { fontSize: 11, fill: SLATE },
                  }}
                />
                <Tooltip />
                <Legend />
                <Bar
                  yAxisId="left"
                  dataKey="pop"
                  name="Deaths / 100k (2022)"
                  fill={INDIGO}
                  radius={[4, 4, 0, 0]}
                >
                  {dualLens.map((r) => (
                    <Cell
                      key={`pop-${r.id}`}
                      fill={r.isUs ? ROSE : INDIGO}
                    />
                  ))}
                </Bar>
                <Bar
                  yAxisId="right"
                  dataKey="vmt"
                  name="Deaths / 100M VMT (2019)"
                  fill={TEAL}
                  radius={[4, 4, 0, 0]}
                >
                  {dualLens.map((r) => (
                    <Cell
                      key={`vmt-${r.id}`}
                      fill={r.isUs ? ORANGE : TEAL}
                    />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      <p className="text-xs leading-relaxed text-slate-500">
        {SOURCE_NOTE} Sources: {SOURCES.join("; ")}.
      </p>
      <span className="sr-only" style={{ color: NAVY }}>
        road safety distance risk dashboard
      </span>
    </div>
  );
}

