  return Object.entries(groups).map(([region, rates]) => ({
    region,
    label: labels[region] ?? region,
    mean: Math.round((rates.reduce((a, b) => a + b, 0) / rates.length) * 100) / 100,
    n: rates.length,
  }));
}

