                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} domain={[0, "auto"]} />
                  <Tooltip />
                  <Legend />
                  <Area
                    type="monotone"
                    dataKey="peerAvg2019"
                    name="2019 peer avg (CDC)"
                    stroke={SLATE}
                    fill="#cbd5e1"
                    fillOpacity={0.25}
                    strokeDasharray="4 4"
                  />
                  <Line
                    type="monotone"
                    dataKey="norwayBand"
                    name="Norway 2021"
                    stroke={TEAL}
                    strokeWidth={2}
                    dot={false}
                  />
                  <Line
                    type="monotone"
                    dataKey="germanyBand"
                    name="Germany 2021"
                    stroke={INDIGO}
                    strokeWidth={2}
                    strokeDasharray="6 3"
                    dot={false}
                  />
                  <Line
                    type="monotone"
                    dataKey="us"
                    name="United States"
                    stroke={ORANGE}
                    strokeWidth={3}
                    dot={{ r: 3 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Selected peers across 2019???21"
            subtitle={`${yLabel} ??? IRTAD Table 4 panel`}
          >
            <div className="h-[360px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={multi}
                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Legend />
                  <Line
                    type="monotone"
                    dataKey="norway"
                    name="Norway"
                    stroke="#34d399"
                    strokeWidth={2}
                    connectNulls
                  />
                  <Line
                    type="monotone"
                    dataKey="germany"
                    name="Germany"
                    stroke="#94a3b8"
                    strokeWidth={2}
                    connectNulls
                  />
                  <Line
                    type="monotone"
                    dataKey="canada"
                    name="Canada"
                    stroke="#fbbf24"
                    strokeWidth={2}
                    connectNulls
                  />
                  <Line
                    type="monotone"
                    dataKey="france"
                    name="France"
                    stroke="#c084fc"
                    strokeWidth={2}
                    connectNulls
                  />
                  <Line
                    type="monotone"
                    dataKey="united-states"
                    name="United States"
                    stroke={ORANGE}
                    strokeWidth={3}
                    connectNulls
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      ) : null}

      {view === "spike" ? (
        <div className="grid gap-6 lg:grid-cols-5">
          <div className="lg:col-span-3">
            <ChartCard
              title="Did the 2020???22 spike reverse?"
              subtitle="US deaths per 100M VMT ??? partial unwind, still above 2019"
            >
              <div className="h-[360px] w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart
                    data={spike}
                    margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                    <YAxis tick={{ fontSize: 11 }} />
                    <Tooltip
                      formatter={(v, name) => [
                        typeof v === "number" ? v.toFixed(2) : v,
                        String(name),
                      ]}
                    />
                    <Legend />
                    <Bar
                      dataKey="rate"
                      name="Rate / 100M VMT"
                      fill={ORANGE}
                      radius={[4, 4, 0, 0]}
                    />
                  </BarChart>
                </ResponsiveContainer>
              </div>
              <p className="mt-3 text-sm text-slate-600">
                From the {HEADLINE.usPeak2021} peak, about{" "}
                <strong>{HEADLINE.spikeUnwindSharePct}%</strong> of the
                2019???2021 jump had unwound by 2024 ??? but the level remains{" "}
                <strong>{HEADLINE.us2024Vs2019Pct}%</strong> above the 2019
                baseline, and still roughly{" "}
                <strong>{spike[spike.length - 1]?.vsNorway2021}??</strong>{" "}
                Norway&apos;s 2021 distance risk.
              </p>
            </ChartCard>
          </div>
          <div className="lg:col-span-2">
            <ChartCard
              title="2019 gap scatter"
              subtitle="CDC MMWR distance rates ??? US vs high-income peers"
            >
              <div className="h-[360px] w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <ScatterChart
                    margin={{ top: 12, right: 12, left: 8, bottom: 12 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis
                      type="number"
                      dataKey="rate"
                      name="Rate"
                      tick={{ fontSize: 11 }}
                      label={{
                        value: "Deaths / 100M VMT (2019)",
                        position: "insideBottom",
                        offset: -4,
                        style: { fontSize: 11, fill: SLATE },
                      }}
                    />
                    <YAxis
                      type="number"
                      dataKey="vsUs"
                      name="US multiple"
                      tick={{ fontSize: 11 }}
                      label={{
                        value: "US ?? country",
                        angle: -90,
                        position: "insideLeft",
                        style: { fontSize: 11, fill: SLATE },
                      }}
                    />
                    <ZAxis range={[60, 60]} />
                    <Tooltip
                      cursor={{ strokeDasharray: "3 3" }}
                      formatter={(v, name) => [
