                  yAxisId="right"
                  orientation="right"
                  tick={{ fontSize: 11 }}
                />
                <Tooltip />
                <Legend />
                <Bar
                  yAxisId="left"
                  dataKey="pop"
                  name="Deaths / 100k (2022)"
                  fill={INDIGO}
                  radius={[4, 4, 0, 0]}
