                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} domain={[0, "auto"]} />
                  <Tooltip />
                  <Legend />
                  <Area
                    type="monotone"
                    dataKey="peerAvg2019"
                    name="2019 peer avg (CDC)"
                    stroke={SLATE}
                    fill="#cbd5e1"
                    fillOpacity={0.25}
                    strokeDasharray="4 4"
                  />
                  <Line
                    type="monotone"
                    dataKey="norwayBand"
                    name="Norway 2021"
                    stroke={TEAL}
                    strokeWidth={2}
                    dot={false}
                  />
                  <Line
                    type="monotone"
                    dataKey="germanyBand"
                    name="Germany 2021"
                    stroke={INDIGO}
                    strokeWidth={2}
                    strokeDasharray="6 3"
                    dot={false}
                  />
                  <Line
                    type="monotone"
                    dataKey="us"
                    name="United States"
                    stroke={ORANGE}
                    strokeWidth={3}
                    dot={{ r: 3 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Selected peers across 2019???21"
            subtitle={`${yLabel} ??? IRTAD Table 4 panel`}
          >
            <div className="h-[360px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={multi}
                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Legend />
                  <Line
                    type="monotone"
                    dataKey="norway"
                    name="Norway"
                    stroke="#34d399"
                    strokeWidth={2}
                    connectNulls
                  />
                  <Line
                    type="monotone"
                    dataKey="germany"
                    name="Germany"
                    stroke="#94a3b8"
                    strokeWidth={2}
                    connectNulls
                  />
                  <Line
                    type="monotone"
                    dataKey="canada"
                    name="Canada"
                    stroke="#fbbf24"
                    strokeWidth={2}
                    connectNulls
                  />
                  <Line
                    type="monotone"
                    dataKey="france"
                    name="France"
                    stroke="#c084fc"
                    strokeWidth={2}
                    connectNulls
                  />
                  <Line
                    type="monotone"
                    dataKey="united-states"
                    name="United States"
                    stroke={ORANGE}
                    strokeWidth={3}
                    connectNulls
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      ) : null}

      {view === "spike" ? (
        <div className="grid gap-6 lg:grid-cols-5">
          <div className="lg:col-span-3">
            <ChartCard
              title="Did the 2020???22 spike reverse?"
              subtitle="US deaths per 100M VMT ??? partial unwind, still above 2019"
