                  interval={0}
                  angle={-35}
                  textAnchor="end"
                  height={60}
                />
                <YAxis yAxisId="left" tick={{ fontSize: 11 }} />
                <YAxis
                  yAxisId="right"
                  orientation="right"
                  tick={{ fontSize: 11 }}
                />
                <Tooltip />
                <Legend />
                <Bar
                  yAxisId="left"
                  dataKey="pop"
                  name="Deaths / 100k (2022)"
                  fill={INDIGO}
                  radius={[4, 4, 0, 0]}
                >
                  {dual.map((r) => (
                    <Cell
